// Same-link test: lowercase the domain only; keep the path/query exactly
// (later capitalization can identify a different page). Ignore a trailing "/".
function normUrl(u){try{const x=new URL(u);const host=x.hostname.toLowerCase();let path=x.pathname.replace(/\/$/,"");return host+path+x.search;}catch(e){return u.trim();}}

