searchEl.addEventListener("input",applySearch);
document.querySelectorAll(".tabs button").forEach(btn=>btn.addEventListener("click",()=>{setTab(btn.dataset.t);render();}));

// ---- permanent delete with confirmation ----
function askDelete(b){
  const ov=document.createElement("div");ov.className="overlay";
  const m=document.createElement("div");m.className="modal";
  m.innerHTML='<h3>Delete this bookmark?</h3><p>“'+esc(b.title||b.url)+'” will be permanently removed. This can’t be undone.</p>';
  const row=document.createElement("div");row.className="row";
  const cancel=document.createElement("button");cancel.className="btn-light";cancel.textContent="Cancel";cancel.addEventListener("click",()=>ov.remove());
  const del=document.createElement("button");del.className="btn-danger";del.textContent="Delete permanently";
  del.addEventListener("click",()=>{const i=bookmarks.findIndex(x=>x.id===b.id);if(i>=0)bookmarks.splice(i,1);if(editingId===b.id)editingId=null;ov.remove();applySearch();});
  row.appendChild(cancel);row.appendChild(del);m.appendChild(row);ov.appendChild(m);document.body.appendChild(ov);
}

// ---- sign-in gate (demo) ----
const DEMO={user:"demo@bookmarks.test",pass:"demo123"};
const signin=document.getElementById("signin"),app=document.getElementById("app");
function doSignIn(){
  const u=document.getElementById("user").value.trim().toLowerCase(),p=document.getElementById("pass").value;
  if(u===DEMO.user&&p===DEMO.pass){signin.style.display="none";app.style.display="block";applySearch();}
  else document.getElementById("signerr").textContent="That email or password isn’t right.";
}
document.getElementById("signbtn").addEventListener("click",doSignIn);
document.getElementById("pass").addEventListener("keydown",e=>{if(e.key==="Enter")doSignIn();});
document.getElementById("signout").addEventListener("click",()=>{app.style.display="none";signin.style.display="block";document.getElementById("pass").value="";});

document.body.setAttribute("data-harness-ready","true");

