    state.currentTags.forEach((tag) => {
      const chip = mkChip(tag, () => { state.currentTags = state.currentTags.filter((t) => t !== tag); renderSaveTags(); renderSuggest(); });
      box.insertBefore(chip, $('taginput'));
    });
