'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { openDb, createDataStore } = require('../../src/db');
const { normalizeUrl } = require('../../src/url');

function freshStore() {
  return createDataStore(openDb(':memory:'));
}
function add(store, userId, url, extra = {}) {
  return store.createBookmark(userId, {
    url, normUrl: normalizeUrl(url), title: extra.title || '', description: extra.description || '',
    note: extra.note || '', tags: extra.tags || [], finished: !!extra.finished, archived: !!extra.archived,
  });
}

test('users are isolated: each sees only their own bookmarks (SCN-013)', () => {
  const s = freshStore();
  const u1 = s.createUser('a@x.com', 'h');
  const u2 = s.createUser('b@x.com', 'h');
  add(s, u1.id, 'https://one.com');
  assert.strictEqual(s.listBookmarks(u1.id).length, 1);
  assert.strictEqual(s.listBookmarks(u2.id).length, 0);
});

test('createBookmark stores tags, note and reading state (SCN-002/008)', () => {
  const s = freshStore();
  const u = s.createUser('a@x.com', 'h');
  const bm = add(s, u.id, 'https://one.com', { title: 'One', note: 'my note', tags: ['a', 'b', 'a'] });
  assert.deepStrictEqual(bm.tags, ['a', 'b']);
  assert.strictEqual(bm.note, 'my note');
  assert.strictEqual(bm.finished, false);
  assert.strictEqual(bm.archived, false);
});

test('findByNormUrl detects duplicates (SCN-006)', () => {
  const s = freshStore();
  const u = s.createUser('a@x.com', 'h');
  add(s, u.id, 'https://github.com/pallets/flask');
  assert.ok(s.findByNormUrl(u.id, normalizeUrl('https://GitHub.com/pallets/flask/')));
  assert.strictEqual(s.findByNormUrl(u.id, normalizeUrl('https://github.com/pallets/Flask')), null);
});

test('update, status, archive and delete (SCN-007/003/011/012)', () => {
  const s = freshStore();
  const u = s.createUser('a@x.com', 'h');
  const bm = add(s, u.id, 'https://one.com', { title: 'One' });
  const up = s.updateBookmark(u.id, bm.id, { url: 'https://one.com/new', normUrl: normalizeUrl('https://one.com/new'), title: 'Renamed', description: 'd', note: 'n', tags: ['x'] });
  assert.strictEqual(up.title, 'Renamed');
  assert.deepStrictEqual(up.tags, ['x']);
  assert.strictEqual(s.setFinished(u.id, bm.id, true).finished, true);
  assert.strictEqual(s.setArchived(u.id, bm.id, true).archived, true);
  assert.ok(s.deleteBookmark(u.id, bm.id));
  assert.strictEqual(s.listBookmarks(u.id).length, 0);
});

test('listTags returns distinct tags for reuse (SCN-002)', () => {
  const s = freshStore();
  const u = s.createUser('a@x.com', 'h');
  add(s, u.id, 'https://one.com', { tags: ['css', 'reference'] });
  add(s, u.id, 'https://two.com', { tags: ['css', 'reading'] });
  assert.deepStrictEqual(s.listTags(u.id), ['css', 'reading', 'reference']);
});

test('sessions resolve to their user and can be destroyed (SCN-013)', () => {
  const s = freshStore();
  const u = s.createUser('a@x.com', 'h');
  s.createSession('tok', u.id);
  assert.strictEqual(s.getSessionUser('tok').id, u.id);
  s.destroySession('tok');
  assert.strictEqual(s.getSessionUser('tok'), null);
});

'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { openDb, createDataStore } = require('../../src/db');
const { createApp } = require('../../src/server');

// Stub metadata fetch so tests never hit the network.
const stubFetch = async (url) => {
  if (url.includes('broken')) throw new Error('boom');
  return {
    ok: true,
    headers: { get: () => 'text/html' },
    text: async () => '<title>Stub Title</title><meta name="description" content="Stub description.">',
  };
};

function startServer() {
  const store = createDataStore(openDb(':memory:'));
  const app = createApp(store, { fetchImpl: stubFetch });
  return new Promise((resolve) => {
    const srv = app.listen(0, '127.0.0.1', () => {
      resolve({ srv, base: `http://127.0.0.1:${srv.address().port}`, store });
    });
  });
}

// Minimal cookie-aware client.
function makeClient(base) {
  let cookie = '';
  return async function call(method, path, body) {
    const headers = {};
    if (cookie) headers.Cookie = cookie;
    if (body !== undefined) headers['Content-Type'] = 'application/json';
    const res = await fetch(base + path, { method, headers, body: body !== undefined ? JSON.stringify(body) : undefined });
    const setc = res.headers.get('set-cookie');
    if (setc) cookie = setc.split(';')[0];
    let data = null; try { data = await res.json(); } catch {}
    return { status: res.status, data };
  };
}

